<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/bootstrap.php';
use App\Core\Auth;use App\Core\Csrf;use App\Core\Database;use App\Services\TestAutomaticJudgeService;
Auth::requireAdmin();$pdo=Database::connection();$roundId=(int)($_GET['round_id']??$_POST['round_id']??0);$notice='';$error='';TestAutomaticJudgeService::ensureSchema($pdo);
try{if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){if(!Csrf::verify($_POST['_csrf']??null))throw new RuntimeException('Invalid security token.');$a=(string)($_POST['action']??'');
 if($a==='delete_judge'){$j=(int)($_POST['judge_id']??0);$pdo->prepare('DELETE FROM bdc_test_scoring_marks WHERE round_id=:r AND judge_id=:j')->execute(['r'=>$roundId,'j'=>$j]);$pdo->prepare('DELETE FROM bdc_test_scoring_judge_sessions WHERE round_id=:r AND judge_id=:j')->execute(['r'=>$roundId,'j'=>$j]);$pdo->prepare('DELETE FROM bdc_test_scoring_judges WHERE round_id=:r AND id=:j')->execute(['r'=>$roundId,'j'=>$j]);$notice='Judge deleted.';}
 elseif($a==='delete_all_judges'){$pdo->prepare('DELETE FROM bdc_test_scoring_marks WHERE round_id=:r')->execute(['r'=>$roundId]);$pdo->prepare('DELETE FROM bdc_test_scoring_judge_sessions WHERE round_id=:r')->execute(['r'=>$roundId]);$pdo->prepare('DELETE FROM bdc_test_scoring_judges WHERE round_id=:r')->execute(['r'=>$roundId]);$notice='All judges deleted.';}
 elseif($a==='delete_entry'){$e=(int)($_POST['entry_id']??0);$pdo->prepare('DELETE FROM bdc_test_scoring_marks WHERE round_id=:r AND entry_id=:e')->execute(['r'=>$roundId,'e'=>$e]);$pdo->prepare('DELETE FROM bdc_test_scoring_entries WHERE round_id=:r AND id=:e')->execute(['r'=>$roundId,'e'=>$e]);$notice='Competitor deleted.';}
 elseif($a==='delete_all_entries'){$pdo->prepare('DELETE FROM bdc_test_scoring_marks WHERE round_id=:r')->execute(['r'=>$roundId]);$pdo->prepare('DELETE FROM bdc_test_scoring_entries WHERE round_id=:r')->execute(['r'=>$roundId]);$notice='All competitors deleted.';}
 elseif($a==='clear_round'){$pdo->beginTransaction();try{$pdo->prepare('DELETE FROM bdc_test_scoring_judge_sessions WHERE round_id=:r')->execute(['r'=>$roundId]);foreach(['bdc_test_scoring_results','bdc_test_scoring_marks','bdc_test_scoring_judges','bdc_test_scoring_entries'] as $t)$pdo->prepare("DELETE FROM {$t} WHERE round_id=:r")->execute(['r'=>$roundId]);$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}$notice='Entire test round cleared.';}
}}catch(Throwable $e){$error=$e->getMessage();}
$rounds=$pdo->query("SELECT r.id,r.division,r.round_type,e.name event_name FROM bdc_test_scoring_rounds r JOIN bdc_test_events e ON e.id=r.event_id ORDER BY r.id DESC LIMIT 50")->fetchAll();$judges=[];$entries=[];if($roundId){$q=$pdo->prepare('SELECT * FROM bdc_test_scoring_judges WHERE round_id=:r ORDER BY judge_order');$q->execute(['r'=>$roundId]);$judges=$q->fetchAll();$q=$pdo->prepare("SELECT * FROM bdc_test_scoring_entries WHERE round_id=:r AND entry_status='active' ORDER BY dance_role,bib_number");$q->execute(['r'=>$roundId]);$entries=$q->fetchAll();}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Manage Test Data</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../../public/css/scoring-premium.css?v=274" rel="stylesheet"></head><body class="bg-light"><nav class="navbar navbar-dark bg-dark"><div class="container-fluid"><span class="navbar-brand">Scoring Tests Data Manager</span><a class="btn btn-outline-light btn-sm" href="select-mode.php">Test Modes</a></div></nav><main class="container py-4"><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php if($notice):?><div class="alert alert-success"><?=e($notice)?></div><?php endif;?><div class="card mb-3"><div class="card-body"><h1 class="h5">Select Test Round</h1><div class="d-flex gap-2 flex-wrap"><?php foreach($rounds as $r):?><a class="btn btn-sm <?=((int)$r['id']===$roundId?'btn-dark':'btn-outline-dark')?>" href="?round_id=<?=(int)$r['id']?>">#<?=(int)$r['id']?> <?=e($r['event_name'])?></a><?php endforeach;?></div></div></div><?php if($roundId):?><div class="d-flex justify-content-end mb-3"><form method="post" onsubmit="return confirm('Clear all judges, competitors, marks and results in this TEST round?')"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="round_id" value="<?=$roundId?>"><input type="hidden" name="action" value="clear_round"><button class="btn btn-danger">Clear Entire Test Round</button></form></div><div class="row g-3"><div class="col-md-6"><div class="card"><div class="card-body"><div class="d-flex justify-content-between"><h2 class="h5">Judges</h2><form method="post"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="round_id" value="<?=$roundId?>"><input type="hidden" name="action" value="delete_all_judges"><button class="btn btn-outline-danger btn-sm">Delete All</button></form></div><table class="table table-sm"><?php foreach($judges as $j):?><tr><td><?=e($j['judge_name'])?><?=((int)$j['is_chief']?' ⭐':'')?></td><td class="text-end"><form method="post"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="round_id" value="<?=$roundId?>"><input type="hidden" name="judge_id" value="<?=(int)$j['id']?>"><input type="hidden" name="action" value="delete_judge"><button class="btn btn-outline-danger btn-sm">Delete</button></form></td></tr><?php endforeach;?></table></div></div></div><div class="col-md-6"><div class="card"><div class="card-body"><div class="d-flex justify-content-between"><h2 class="h5">Competitors</h2><form method="post"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="round_id" value="<?=$roundId?>"><input type="hidden" name="action" value="delete_all_entries"><button class="btn btn-outline-danger btn-sm">Delete All</button></form></div><table class="table table-sm"><?php foreach($entries as $e):?><tr><td>#<?=(int)$e['bib_number']?> <?=e($e['display_name'])?></td><td><?=e($e['dance_role'])?></td><td class="text-end"><form method="post"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="round_id" value="<?=$roundId?>"><input type="hidden" name="entry_id" value="<?=(int)$e['id']?>"><input type="hidden" name="action" value="delete_entry"><button class="btn btn-outline-danger btn-sm">Delete</button></form></td></tr><?php endforeach;?></table></div></div></div></div><?php endif;?></main></body></html>